import keeps_recurring from "./keeps_recurring";
import which_system from "./which_system";
import select_by_flags from "./select_by_flags";
import group_count from "./group_count";
import count_if from "./count_if";
import halve from "./halve";
import is_small from "./is_small";
---
description: A synthesized program.
returns: Num
---
function incident_overview(alerts) -> { breakdown: Dict<Num>, count: Num, shifts_needed: Num }

  recurring = [keeps_recurring(x) for x in alerts]
  systems = map(x => which_system(x), alerts)
  shortlist = select_by_flags(alerts, recurring)
  if shortlist is empty:
      breakdown = {}
  else:
      components = [which_system(x) for x in shortlist]
      breakdown = group_count(components)
  is_storage = for each l in systems: l == "storage"          # exact: use code
  count = carry a count through is_storage, starting at 0: count_if(acc, item)
  shifts_needed = repeat at most 8 times, until is_small(state): state = halve(state), starting from count
  return { breakdown, count, shifts_needed }

import mentions_side_effects from "./mentions_side_effects";
import kind_of_study from "./kind_of_study";
import in_adults from "./in_adults";
import select_by_flags from "./select_by_flags";
import group_count from "./group_count";
---
description: A synthesized program.
returns: Num
---
function abstract_triage(abstracts) -> { by_topic: Dict<Num>, by_designs: Dict<Num>, share: Num }

  let side_effects = for x in abstracts do mentions_side_effects(x)
  let designs = for x in abstracts do kind_of_study(x)
  let adults_only = for x in abstracts do in_adults(x)
  subset = select_by_flags(abstracts, adults_only)
  if subset is empty:
      by_topic = {}
  else:
      study_kinds = [kind_of_study(x) for x in subset]
      by_topic = group_count(study_kinds)
  by_designs = group_count(designs)
  share = share of true in side_effects, rounded to 2 decimals     # exact
  return { by_topic, by_designs, share }

import clause_type from "./clause_type";
import is_onesided from "./is_onesided";
import select_by_flags from "./select_by_flags";
import group_count from "./group_count";
import count_if from "./count_if";
---
description: A synthesized program.
returns: Num
---
function clause_checklist(clauses) -> { by_kind: Dict<Num>, n_either_flag: Num }

  clause_types = for each x in clauses: clause_type(x)
  payment_flags = for each l in clause_types: l == "payment"          # exact: use code
  let onesided = for x in clauses do is_onesided(x)
  shortlist = select_by_flags(clauses, payment_flags)
  if shortlist is empty:
      by_kind = {}
  else:
      kinds = map(x => clause_type(x), shortlist)
      by_kind = group_count(kinds)
  either_flag = position by position: onesided or payment_flags          # exact: use code
  n_either_flag = carry a count through either_flag, starting at 0: count_if(acc, item)
  return { by_kind, n_either_flag }

import subsystem_of from "./subsystem_of";
import tally from "./tally";
import act_before_next_pass from "./act_before_next_pass";
import select_by_flags from "./select_by_flags";
import group_count from "./group_count";
---
description: A synthesized program.
returns: Num
---
function housekeeping_check(readings) -> { by_parts: Dict<Num>, breakdown: Dict<Num>, share_is_power: Num }

  parts = readings.map(x -> subsystem_of(x))
  by_parts = carry a tally through parts, starting at {}: tally(acc, item)
  action_flags = map(x => act_before_next_pass(x), readings)
  shortlist = select_by_flags(readings, action_flags)
  if shortlist is empty:
      breakdown = {}
  else:
      subsystems = [subsystem_of(x) for x in shortlist]
      breakdown = group_count(subsystems)
  is_power = for each l in parts: l == "power"          # exact: use code
  share_is_power = share of true in is_power, rounded to 2 decimals     # exact
  return { by_parts, breakdown, share_is_power }

import classify from "./classify";
import is_angry from "./is_angry";
import group_count from "./group_count";
import count_if from "./count_if";
---
description: A synthesized program.
returns: Num
---
function support_digest(tickets, rubric) -> { counts: Dict<Num>, n_upset: Num }

  categories = for each x in tickets: classify(x, rubric)
  let upset = for x in tickets do is_angry(x)
  counts = group_count(categories)
  n_upset = carry a count through upset, starting at 0: count_if(acc, item)
  return { counts, n_upset }

import mentions_side_effects from "./mentions_side_effects";
import select_by_flags from "./select_by_flags";
import kind_of_study from "./kind_of_study";
import group_count from "./group_count";
import count_true from "./count_true";
import in_adults from "./in_adults";
---
description: A synthesized program.
returns: Num
---
function abstract_triage(abstracts) -> { by_topic: Dict<Num>, count: Num, share_adult_flags: Num, share: Num }

  if abstracts is empty:
      return { by_topic: {}, count: 0, share_adult_flags: 0, share: 0 }
  let side_effects = for x in abstracts do mentions_side_effects(x)
  chosen = select_by_flags(abstracts, side_effects)
  if chosen is empty:
      by_topic = {}
  else:
      designs = [kind_of_study(x) for x in chosen]
      by_topic = group_count(designs)
  count = count_true(side_effects)
  adult_flags = [in_adults(x) for x in abstracts]
  share_adult_flags = share of true in adult_flags, rounded to 2 decimals     # exact
  any_flag = position by position: adult_flags or side_effects          # exact: use code
  share = share of true in any_flag, rounded to 2 decimals     # exact
  return { by_topic, count, share_adult_flags, share }

