match_route.code:
const hit = args.routes.find(r => r.path === args.req.path)
if (!hit) return { kind: "not_found", name: args.req.path, purpose: "", asset: "" }
if (!hit.methods.includes(args.req.method)) return { kind: "method_not_allowed", name: hit.path, purpose: hit.methods.join(", "), asset: "" }
return { kind: hit.kind, name: hit.path, purpose: hit.purpose, asset: hit.asset || "" }

parse_request.code:
const dec = s => { try { return decodeURIComponent(s.replace(/\+/g, " ")) } catch (e) { return s } }
const pairs = s => Object.fromEntries((s || "").split("&").filter(Boolean).map(p => { const i = p.indexOf("="); return i < 0 ? [dec(p), ""] : [dec(p.slice(0, i)), dec(p.slice(i + 1))] }))
const [path, qs] = args.item.path.split("?")
const cookie = Object.entries(args.item.headers).find(([k]) => lower(k) === "cookie")
const sid = cookie ? (cookie[1].match(/(?:^|;\s*)sid=([A-Za-z0-9_-]+)/) || [])[1] : ""
return { id: args.item.id, method: args.item.method.toUpperCase(), path: path.replace(/\/+$/, "") || "/", query: pairs(qs),
         form: args.item.method.toUpperCase() === "POST" ? pairs(args.item.body) : {}, session_id: sid || "" }

session_for.code:
const old = args.acc.sessions[args.req.session_id]
if (old) return { ...old, visits: old.visits + 1 }
return { id: "s" + (Object.keys(args.acc.sessions).length + 1) + "x" + args.req.id.replace(/[^A-Za-z0-9]/g, ""), visits: 1, name: "" }

